function nzss_clean_attributes(mixed $raw): array {
    if(!is_array($raw))return[];$out=[];foreach($raw as$key=>$value){if(count($out)>=30)break;$label=mb_substr(trim((string)$key),0,80);if($label===''||is_array($value))continue;$val=mb_substr(trim((string)$value),0,300);if($val!=='')$out[$label]=$val;}return$out;
}
function nzss_location_id(string $type,string $value): string {$normalized=nzm_normalize($value);return$normalized===''?'':$type.'_'.substr(hash('sha256',$normalized),0,12);}
function nzss_handle_create(): never {
    nzc_session_open();$db=nzc_db_read();$user=nzc_require_user($db);if(nzc_user_blocked($db,(string)$user['id']))throw new RuntimeException('این حساب فعلاً اجازه ثبت آگهی جدید ندارد.');if(!nzc_csrf_valid())throw new RuntimeException('درخواست نامعتبر است. صفحه را تازه‌سازی کنید.');
    $title=trim((string)($_POST['title']??''));$desc=trim((string)($_POST['description']??''));$category=trim((string)($_POST['category']??''));$subcategory=trim((string)($_POST['subcategory']??''));$province=trim((string)($_POST['province']??''));$city=trim((string)($_POST['city']??''));$district=mb_substr(trim((string)($_POST['district']??'')),0,100);$street=mb_substr(trim((string)($_POST['street']??'')),0,180);$mode=(string)($_POST['location_mode']??'approx');if(!in_array($mode,['exact','approx'],true))$mode='approx';
    $titleLen=mb_strlen($title);$descLen=mb_strlen($desc);if($titleLen<5)throw new RuntimeException('عنوان آگهی حداقل ۵ حرف باشد.');if($titleLen>120)throw new RuntimeException('عنوان آگهی حداکثر ۱۲۰ حرف باشد.');if($descLen<15)throw new RuntimeException('توضیحات آگهی را کامل‌تر بنویسید.');if($descLen>5000)throw new RuntimeException('توضیحات آگهی حداکثر ۵۰۰۰ حرف باشد.');if($category===''||$subcategory==='')throw new RuntimeException('دسته و زیر‌دسته آگهی را انتخاب کنید.');if($province===''||$city==='')throw new RuntimeException('استان و شهر آگهی را انتخاب کنید.');nzt_validate($category,$subcategory,$province,$city);
    $latRaw=$_POST['latitude']??null;$lngRaw=$_POST['longitude']??null;if(!is_numeric($latRaw)||!is_numeric($lngRaw))throw new RuntimeException('موقعیت آگهی را روی نقشه مشخص کنید.');$lat=(float)$latRaw;$lng=(float)$lngRaw;if($lat<24||$lat>40.5||$lng<43||$lng>64)throw new RuntimeException('موقعیت انتخاب‌شده خارج از محدوده قابل قبول است.');if($mode==='approx'){$lat=round($lat,3);$lng=round($lng,3);}
    $attributes=nzss_clean_attributes($_POST['attributes']??[]);nzcv_validate($category,$subcategory,$attributes);$price=max(0,(int)($_POST['price']??0));if($price>999999999999)throw new RuntimeException('مبلغ واردشده خارج از محدوده قابل قبول است.');$duplicateMeta=nzdg_guard($db,$user,$category,$subcategory,$title,$desc,$attributes,$price,$_FILES['images']??[]);$clientModeration=nzm_scan_submission($title,$desc,$attributes);$serverModeration=nzsm_scan_uploads($_FILES['images']??[]);$moderation=nzsm_merge($clientModeration,$serverModeration);
    $images=[];$video=null;$videoDuration=null;
    try{
        $images=nzcp_process_images($_FILES['images']??[]);if(!$images)throw new RuntimeException('حداقل یک عکس برای آگهی انتخاب کنید.');[$video,$videoDuration]=nzcp_process_video($_FILES['video']??[],(float)($_POST['video_duration']??0));
        $provinceId=nzss_location_id('province',$province);$cityId=nzss_location_id('city',$province.'|'.$city);$districtId=$district!==''?nzss_location_id('district',$province.'|'.$city.'|'.$district):'';$post=['id'=>nzc_uid('p'),'user_id'=>$user['id'],'title'=>$title,'description'=>$desc,'category'=>$category,'subcategory'=>$subcategory,'province'=>$province,'province_id'=>$provinceId,'city'=>$city,'city_id'=>$cityId,'district'=>$district,'district_id'=>$districtId,'street'=>$street,'latitude'=>$lat,'longitude'=>$lng,'location_mode'=>$mode,'location'=>['province'=>$province,'province_id'=>$provinceId,'city'=>$city,'city_id'=>$cityId,'district'=>$district,'district_id'=>$districtId,'street'=>$street,'lat'=>$lat,'lng'=>$lng,'mode'=>$mode],'attributes'=>$attributes,'price'=>$price,'images'=>$images,'image_fingerprints'=>$duplicateMeta['image_fingerprints']??[],'duplicate_fingerprint'=>$duplicateMeta['duplicate_fingerprint']??'','video'=>$video,'video_duration'=>$videoDuration,'chat_enabled'=>isset($_POST['chat_enabled']),'phone_visible'=>isset($_POST['phone_visible']),'status'=>'pending','review_status'=>'pending','review_priority'=>!empty($moderation['flagged'])?'high':'normal','moderation'=>$moderation,'featured'=>false,'views'=>0,'created_at'=>nzc_now(),'submitted_at'=>nzc_now(),'updated_at'=>nzc_now()];
        nzc_db_write(function(&$db)use($post){$db['posts'][]=$post;if(!empty($post['moderation']['flagged']))nzm_add_system_report($db,$post);$suffix=!empty($post['moderation']['flagged'])?' این آگهی توسط پایش خودکار برای بررسی فوری مدیر علامت‌گذاری شده است.':'';nzc_support_message($db,$post['user_id'],'آگهی «'.$post['title'].'» دریافت شد و برای بررسی مدیر ارسال شد. تا زمان تأیید مدیر برای سایر کاربران نمایش داده نمی‌شود.'.$suffix);nzc_notify($db,$post['user_id'],'آگهی «'.$post['title'].'» در انتظار تأیید مدیر است.',!empty($post['moderation']['flagged'])?'high':'normal');});
    }catch(Throwable $e){$cleanup=$images;if($video)$cleanup[]=$video;if(function_exists('nzcp_delete_media'))nzcp_delete_media($cleanup);throw $e;}
    nzc_audit($user,'create_post','post',(string)$post['id'],['category'=>$category,'subcategory'=>$subcategory,'priority'=>$post['review_priority']]);if(!empty($moderation['flagged']))nzc_flash('آگهی ثبت شد و به دلیل محتوای مشکوک یا ناقص بودن بررسی خودکار با اولویت بالا برای مدیر ارسال شد. تا تصمیم مدیر منتشر نمی‌شود.','warn');else nzc_flash('آگهی برای بررسی مدیر ارسال شد. نتیجه در چت پشتیبانی اعلام می‌شود.','ok');nzc_redirect('/nz?page=myposts');
}